class Solution:
    def appealSum(self, s: str) -> int:
        ans = cur = 0
        last = [-1] * 26
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            cur += i - last[c]
            ans += cur
            last[c] = i
        return ans

