class Solution {
public:
    long long appealSum(string s) {
        long long ans = 0, cur = 0;
        int last[26];
        fill(last, last + 26, -1);
        for (int i = 0; i < (int)s.size(); i++) {
            int c = s[i] - 'a';
            cur += i - last[c];
            ans += cur;
            last[c] = i;
        }
        return ans;
    }
};

