class Solution:
    def appealSum(self, s: str) -> int:
        n = len(s)
        ans = 0
        last = [-1] * 26
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            ans += (i - last[c]) * (n - i)
            last[c] = i
        return ans

